def settle(self) -> Dict[Any, int]:

    Operand order follows CIRCT: ``(input, clock[, reset, resetValue])``.
    """

    OPERATION_NAME = "seq.compreg"

    #: Operand indices.
    INPUT = 0
    CLOCK = 1
    RESET = 2
    RESET_VALUE = 3

    def __init__(
        self,
        name: Optional[str] = None,
        width: int = 0,
        input_signal: Optional[Union[Value, str]] = None,
        clock: Union[Value, str] = "clk",
        reset: Optional[Union[Value, str]] = None,
        reset_value: int = 0,
        reset_type: ResetType = ResetType.SYNC,
        current_value: int = 0,
        clock_domain: Optional[ClockDomain] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        if not ops:
            if input_signal is not None:
                ops.append(input_signal)
            ops.append(clock)
            if reset is not None:
                ops.append(reset)
        attrs: Dict[str, Attribute] = dict(attributes or {})
        if name:
            attrs.setdefault("name", StringAttr(name))
        super().__init__(
            operands=ops,
            result_types=result_types,
            attributes=attrs,
            width=width,
            result_name=name or "",
            location=location,
        )
        self.reg_name = name or ""
        self.reset_value = int(reset_value)
        self.reset_type = reset_type
        self.current_value = int(current_value)
        self.clock_domain = clock_domain
        self.cycles_ticked = 0

    @classmethod
    def build_parsed(cls, **kwargs: Any) -> Operation:
        op = super().build_parsed(**kwargs)
        name_attr = kwargs.get("attributes", {}).get("name")
        op.reg_name = name_attr.value if name_attr is not None else op.result_name
        op.reset_type = ResetType.SYNC
        op.reset_value = 0
        op.current_value = 0
        op.clock_domain = None
        op.cycles_ticked = 0
        return op

    # -- operand accessors -------------------------------------------------
    @property
    def has_reset(self) -> bool:
        return self.num_operands > self.RESET

    @property
    def input_signal(self) -> Any:
        return self.get_operand(self.INPUT) if self.num_operands > self.INPUT else None

    @property
    def clock(self) -> Any:
        return self.get_operand(self.CLOCK) if self.num_operands > self.CLOCK else None

    @property
    def reset(self) -> Any:
        return self.get_operand(self.RESET) if self.has_reset else None

    def declared_reset_value(self, env: SignalEnv) -> int:
        """The reset value, read from the operand when the IR supplies one."""
        if self.num_operands > self.RESET_VALUE:
            return self.read_operand(env, self.RESET_VALUE)
        return self.reset_value

    def reset_active(self, env: SignalEnv) -> bool:
        if not self.has_reset:
            return False
        if self.reset_type is ResetType.NONE:
            return False
        return bool(self.read_operand(env, self.RESET) & 1)

    def async_reset(self, env: Optional[SignalEnv] = None) -> bool:
        env = env or {}
        return self.reset_type is ResetType.ASYNC and self.reset_active(env)

    # -- clocked behaviour -------------------------------------------------
    def next_value(self, env: SignalEnv) -> int:
        if self.reset_active(env):
            return self.truncate(self.declared_reset_value(env))
        return self.truncate(self.read_operand(env, self.INPUT))

    def reset_state(self, env: Optional[SignalEnv] = None) -> None:
        self.current_value = self.truncate(self.declared_reset_value(env or {}))
        self.cycles_ticked = 0

    def verify_op(self) -> List[str]:
        if self.num_operands < 2:
            return ["'seq.compreg' expects at least an input and a clock operand"]
        return []


