    RESET_VALUE = 4

    def __init__(
        self,
        name: Optional[str] = None,
        width: int = 0,
        input_signal: Optional[Union[Value, str]] = None,
        clock: Union[Value, str] = "clk",
        clock_enable: Union[Value, str] = "ce",
        reset: Optional[Union[Value, str]] = None,
        reset_value: int = 0,
        reset_type: ResetType = ResetType.SYNC,
        current_value: int = 0,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        location: Optional[Location] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        if not ops:
            if input_signal is not None:
                ops.append(input_signal)
            ops.append(clock)
            ops.append(clock_enable)
            if reset is not None:
                ops.append(reset)
        super().__init__(
            name=name,
            width=width,
            reset_value=reset_value,
            reset_type=reset_type,
            current_value=current_value,
            operands=ops,
            result_types=result_types,
            location=location,
        )

    @property
    def has_reset(self) -> bool:
        return self.num_operands > self.RESET

    def is_enabled(self, env: Optional[SignalEnv] = None) -> bool:
        if self.num_operands <= self.CLOCK_ENABLE:
            return True
        return bool(self.read_operand(env or {}, self.CLOCK_ENABLE, default=1) & 1)

    def next_value(self, env: SignalEnv) -> int:
        if self.reset_active(env):
            return self.truncate(self.declared_reset_value(env))
        if not self.is_enabled(env):
            return self.truncate(self.current_value)
        return self.truncate(self.read_operand(env, self.INPUT))


