    def preset(self) -> None:
        if self.preset_value is not None:
            self.current_value = self.truncate(self.preset_value)

    def next_value(self, env: SignalEnv) -> int:
        if self.num_operands > self.RESET and self.read_operand(env, self.RESET) & 1:
            if self.num_operands > self.RESET_VALUE:
                return self.truncate(self.read_operand(env, self.RESET_VALUE))
            return self.truncate(self.reset_value)
        return self.truncate(self.read_operand(env, self.INPUT))

    def tick(self, env: Optional[SignalEnv] = None, next_value: Optional[int] = None) -> int:
        """Commit ``next_value`` if given, otherwise compute it from ``env``."""
        if next_value is not None:
            return self.commit(next_value)
        return self.commit(self.next_value(env or {}))


